    const navigation=`<nav class="st-department-tabs" aria-label="Departments">${data.departments.map(d=>`<button data-action="department" data-id="${e(d.id)}" aria-pressed="${department===d.id}"><strong>${e(d.label)}</strong><small>${openTasks().filter(t=>t.department===d.id).length} open</small></button>`).join('')}</nav>`;
