    const expanded=[...document.querySelectorAll('[data-daily-disclosure][open]')].map(el=>el.dataset.dailyDisclosure);
    // Bulk changes on a company's Tasks tab; the selection resets when the view changes.
    {const v=view==='company'&&companyTab==='tasks'?'company:'+selected:view;if(v!==bulkView){window.WorkspaceBulk?.clear();bulkView=v;}picking=!!window.WorkspaceBulk&&v.startsWith('company:')&&canEdit();}
